def valid_parentheses(paren_str):
    open_parentheses = set("([{")
    close_parentheses = set(")]}")
    paren_stack = []
    for i in paren_str:
        if i in open_parentheses:
            paren_stack.append(i)
        elif i in close_parentheses:
