def balanced_parentheses(expression):
    stack = []
    open_parentheses = ["(", "[", "{"]
    closed_parentheses = [")", "]", "}"]

    for char in expression:
        if char in open_parentheses:
            stack.append(char)
        elif char in closed_parentheses:
            if not stack:
                return False
            if (closed_parentheses.index(char) == open_parentheses.index(stack.pop())): 
                continue
            else:
                return False

    if stack:
        return False

