def common_prefix(strs):
    if not strs:
        return ''
    if len(strs) == 1:
        return strs[0]
    min_length = min([len(s) for s in strs])
    common_prefix = ''
    for i in range(min_length):
        current_char = strs[0][i]
        for j in range(1, len(strs)):
            if strs[j][i] != current_char:
                return common_prefix
        common_prefix += current_char
    return common_prefix
